/**
 * A translated string, safe to concatenate into this file's markup.
 *
 * Every interpolated VALUE is escaped here, before it can reach the message.
 * The messages themselves contain no markup — `<` means nothing to ICU but
 * IS rich-tag syntax to formatjs and to Flarum's own RichMessageFormatter,
 * so a message carrying `<b>` is one that can never be reused from JS. The
 * `<b>` stays in the concatenation below, where it belongs.
 */
private function t(string $key, array $params = []): string
{
    foreach ($params as $k => $v) {
        if (is_string($v)) {
            $params[$k] = $this->esc($v);
        }
    }

    return (string) resolve(\Symfony\Contracts\Translation\TranslatorInterface::class)
        ->trans('local-looksmax-index.'.$key, $params);
}

/**
 * A figure grouped the way this reader's locale groups it.
 *
 * Not number_format(), which is hardwired to the English 1,234 — and not an
 * ICU `{n, number}` key either, because ICU would be handed Flarum's locale
 * code `es`, and GENERIC Spanish groups differently from MEXICAN Spanish.
 * Measured against CLDR:
 *
 *     es -> 12.431      es-MX -> 12,431      es-419 -> 12,431      en -> 12,431
 *
 * The audience here is Mexican, and window.lmxI18n already maps es -> es-MX
 * for everything it formats on the client (looksmax-i18n/js/dist/forum.js:44).
 * Without the same mapping on this side, the server-rendered index would
 * print 12.431 beside a client-rendered search result printing 12,431, on
 * the same page.
 */
private function n(int $v): string
{
    $locale = resolve(\Symfony\Contracts\Translation\TranslatorInterface::class)->getLocale();
    if ($locale === 'es') {
        $locale = 'es-MX';
    }

    if (class_exists(\NumberFormatter::class)) {
        $formatted = (new \NumberFormatter($locale, \NumberFormatter::DECIMAL))->format($v);
        if ($formatted !== false) {
            return $formatted;
        }
    }

    return number_format($v);
}

