/**
 * A figure grouped for the active locale: 12,431 in English, 12.431 in
 * Spanish. `lib.number` is the one-line ICU message `{n, number}`; routing
 * through the translator rather than number_format() is what makes the
 * separator follow the reader instead of the source file.
 */
private function n(int $v): string
{
    return $this->t('lib.number', ['n' => $v]);
}

